336	+import {
337	+  type RelayEntry,
338	+  relayCredentialsUrl,
339	+  relayEntry,
340	+} from '@wolsok/feat-shared-bacteria-engine/cloud';
341	+
342	+/**
343	+ * The TURN key of Cloudflare Realtime that hands out the relay's
344	+ * credentials (ADR 0020): its id and its token, as the provisioning tool
345	+ * (`tools-relay:turn-key`) stores them in the secret `CLOUDFLARE_TURN_KEY`.
346	+ * The token can only hand out credentials, never change the account.
347	+ */
348	+export interface TurnKey {
349	+  id: string;
350	+  token: string;
351	+}
352	+
353	+/** The longest wait for Cloudflare's answer. */
354	+const FETCH_TIMEOUT_MS = 10_000;
355	+
356	+/** The `CLOUDFLARE_TURN_KEY` secret's value, which names no part of it on failure. */
357	+export function parseTurnKey(secret: string): TurnKey {
358	+  let value: unknown = null;
359	+  try {
360	+    value = JSON.parse(secret);
361	+  } catch {
362	+    // Reported below without the value.
363	+  }
364	+  const { id, token } = (value ?? {}) as Record<string, unknown>;
365	+  if (
366	+    typeof id !== 'string' ||
367	+    id === '' ||
368	+    typeof token !== 'string' ||
369	+    token === ''
370	+  ) {
371	+    throw new Error('CLOUDFLARE_TURN_KEY is no {"id","token"} JSON.');
372	+  }
373	+  return { id, token };
374	+}
375	+
376	+/**
377	+ * Fresh credentials for the relay, valid `ttlSeconds` - throws when
378	+ * Cloudflare refuses or answers no TURN server, never with the token or
379	+ * Cloudflare's text in the message.
380	+ */
381	+export async function fetchRelay(
382	+  key: TurnKey,
383	+  ttlSeconds: number,
384	+  fetchFn: typeof fetch
385	+): Promise<RelayEntry> {
386	+  const response = await fetchFn(relayCredentialsUrl(key.id), {
387	+    method: 'POST',
388	+    headers: {
389	+      Authorization: `Bearer ${key.token}`,
390	+      'Content-Type': 'application/json',
391	+    },
392	+    body: JSON.stringify({ ttl: ttlSeconds }),
393	+    signal: AbortSignal.timeout(FETCH_TIMEOUT_MS),
394	+  });
395	+  if (!response.ok) {
396	+    throw new Error(
397	+      `Cloudflare refused the TURN credentials (${response.status}).`
398	+    );
399	+  }
400	+  const entry = relayEntry(await response.json());
401	+  if (entry === null) {
402	+    throw new Error('Cloudflare answered no TURN server.');
403	+  }
404	+  return entry;
405	+}
