685	+import { isObject } from '../../is-object';
686	+import type { ToMillis } from './ban';
687	+
688	+/** The collection of the relay's credentials (ADR 0020). */
689	+export const RELAY_COLLECTION = 'relay';
690	+/** The one document in it: Cloudflare's TURN server. */
691	+export const RELAY_DOC_ID = 'turn';
692	+
693	+/**
694	+ * The TURN relay's credentials as `relay/turn` stores them (ADR 0020):
695	+ * where the relay is, and the short-lived name and password that let a
696	+ * device use it until `expireAt`, in ms. Only the functions write it
697	+ * (`refreshRelay`, every 30 minutes); the game reads it with
698	+ * {@link parseRelayCredentials} before it connects to another device.
699	+ * Flat, since Firestore here holds no arrays in arrays.
700	+ */
701	+export interface RelayCredentials {
702	+  /** The relay's `turn:` and `turns:` URLs. */
703	+  urls: string[];
704	+  username: string;
705	+  credential: string;
706	+  /** When the credentials stop working. */
707	+  expireAt: number;
708	+}
709	+
710	+/**
711	+ * `relay/turn` - null for no document, or one the relay cannot be used
712	+ * with: no URL, no name or password, or no readable expiry.
713	+ */
714	+export function parseRelayCredentials(
715	+  data: unknown,
716	+  toMillis: ToMillis
717	+): RelayCredentials | null {
718	+  if (!isObject(data) || !Array.isArray(data['urls'])) {
719	+    return null;
720	+  }
721	+  const urls = data['urls'].filter(
722	+    (url): url is string => typeof url === 'string'
723	+  );
724	+  const username = data['username'];
725	+  const credential = data['credential'];
726	+  const expireAt = toMillis(data['expireAt']);
727	+  if (
728	+    urls.length === 0 ||
729	+    typeof username !== 'string' ||
730	+    username === '' ||
731	+    typeof credential !== 'string' ||
732	+    credential === '' ||
733	+    expireAt === null
734	+  ) {
735	+    return null;
736	+  }
737	+  return { urls, username, credential, expireAt };
738	+}
739	+
740	+/** The TURN server as Cloudflare hands it out and `relay/turn` keeps it. */
741	+export type RelayEntry = Omit<RelayCredentials, 'expireAt'>;
742	+
743	+/**
744	+ * Where Cloudflare Realtime hands out credentials for the TURN key
745	+ * `keyId`: a POST with the key's token and `{ ttl }` in seconds.
746	+ */
747	+export function relayCredentialsUrl(keyId: string): string {
748	+  return `https://rtc.live.cloudflare.com/v1/turn/keys/${encodeURIComponent(keyId)}/credentials/generate-ice-servers`;
749	+}
750	+
751	+/**
752	+ * A URL on port 53, which browsers block: without trickle ICE, which the
753	+ * game does not use, it only times out (Cloudflare's advice).
754	+ */
755	+const PORT_53 = /:53(\?|$)/;
756	+
757	+/**
758	+ * The TURN server in Cloudflare's `generate-ice-servers` answer, its URLs
759	+ * on port 53 dropped - null when it has none left, or no credentials.
760	+ * The STUN entry is left out: the game has its own STUN servers.
761	+ */
762	+export function relayEntry(answer: unknown): RelayEntry | null {
763	+  const servers = isObject(answer) ? answer['iceServers'] : null;
764	+  if (!Array.isArray(servers)) {
765	+    return null;
766	+  }
767	+  for (const server of servers) {
768	+    if (!isObject(server)) {
769	+      continue;
770	+    }
771	+    const { username, credential } = server;
772	+    const listed = server['urls'];
773	+    const urls = (Array.isArray(listed) ? listed : [listed]).filter(
774	+      (url): url is string =>
775	+        typeof url === 'string' && /^turns?:/.test(url) && !PORT_53.test(url)
776	+    );
777	+    if (
778	+      urls.length > 0 &&
779	+      typeof username === 'string' &&
780	+      typeof credential === 'string'
781	+    ) {
782	+      return { urls, username, credential };
783	+    }
784	+  }
785	+  return null;
786	+}
