234	/**
235	 * Two connections in one Chromium page that may reach each other only
236	 * through `relay` (`iceTransportPolicy: 'relay'`), as two devices behind
237	 * strict NATs: whether their channel opens, carries a message, and still
238	 * carries one {@link CHECK_HOLD_MS} later, past the credentials' expiry.
239	 */
240	export async function checkRelay(
241	  relay: RelayEntry,
242	  holdMs = CHECK_HOLD_MS
243	): Promise<RelayCheck> {
244	  const browser = await chromium.launch();
245	  try {
246	    const page = await browser.newPage();
247	    // tsx names the functions it compiles with an `__name` helper, which
248	    // the page does not have.
249	    await page.evaluate('globalThis.__name = (fn) => fn');
250	    return await page.evaluate(
251	      async ({ relay, holdMs }) => {
252	        const config: RTCConfiguration = {
253	          iceServers: [relay],
254	          iceTransportPolicy: 'relay',
255	        };
256	        const a = new RTCPeerConnection(config);
257	        const b = new RTCPeerConnection(config);
258	        a.onicecandidate = ({ candidate }) =>
259	          candidate && void b.addIceCandidate(candidate);
260	        b.onicecandidate = ({ candidate }) =>
261	          candidate && void a.addIceCandidate(candidate);
262	        const options = { negotiated: true, id: 0, ordered: true };
263	        const out = a.createDataChannel('check', options);
264	        const into = b.createDataChannel('check', options);
265	        const received: string[] = [];
266	        into.onmessage = ({ data }) => received.push(String(data));
267	        const wait = (ms: number) =>
268	          new Promise((resolve) => setTimeout(resolve, ms));
269	        const until = async (done: () => boolean, ms: number) => {
270	          for (let left = ms; left > 0 && !done(); left -= 100) {
271	            await wait(100);
272	          }
273	          return done();
274	        };
275	
276	        await a.setLocalDescription(await a.createOffer());
277	        await b.setRemoteDescription(
278	          a.localDescription as RTCSessionDescription
279	        );
280	        await b.setLocalDescription(await b.createAnswer());
281	        await a.setRemoteDescription(
282	          b.localDescription as RTCSessionDescription
283	        );
284	
285	        const opened = await until(() => out.readyState === 'open', 20_000);
286	        let relayed = false;
287	        const stats = await a.getStats();
288	        stats.forEach((report) => {
289	          if (report.type === 'transport' && report.selectedCandidatePairId) {
290	            const pair = stats.get(report.selectedCandidatePairId);
291	            relayed =
292	              stats.get(pair?.localCandidateId)?.candidateType === 'relay' &&
293	              stats.get(pair?.remoteCandidateId)?.candidateType === 'relay';
294	          }
295	        });
296	        if (opened) {
297	          out.send('first');
298	        }
299	        const first = await until(() => received.includes('first'), 10_000);
300	        await wait(holdMs);
301	        if (out.readyState === 'open') {
302	          out.send('after');
303	        }
304	        const afterExpiry = await until(
305	          () => received.includes('after'),
306	          10_000
307	        );
308	        a.close();
309	        b.close();
310	        return { opened, relayed, first, afterExpiry };
311	      },
312	      { relay, holdMs }
313	    );
314	  } finally {
315	    await browser.close();
316	  }
317	}
